    private static void Check(bool v,string m){if(!v)throw new Exception(m);}
    private static void Reject(Action a){bool rejected=false;try{a();}catch(ArgumentException){rejected=true;}Check(rejected,"Invalid Trainer8 edit accepted");}
    private static uint Hash(string n)=>(uint)FnvHash.HashFnv1a_64(n.AsSpan());
