    private static readonly HashSet<uint> Counts=Zones.Select(z=>Hash($"WK_EV_R1_DHIG_WR{z.Zone:0000}")).Concat(new[]{"WK_EV_R1_DHIGUDA_ADD","WK_EV_R1_DHIGUDA_COUNT","WK_EV_R1_DHIGUDA_PROGRESS"}.Select(Hash)).ToHashSet();
    private static readonly HashSet<uint> Flags=Zones.SelectMany(z=>Enumerable.Range(0,z.Max+1).Select(i=>Hash($"z_wr{z.Zone:0000}_F_DHIGUDA_{i}")).Append(Hash($"z_wr{z.Zone:0000}_F_DHIGUDA"))).Concat(new[]{Hash("z_wr0223_F_TRIO"),Hash("FE_R1_DHIGUDA_TRIO")}).ToHashSet();
    private static SAV8SWSH Open(byte[] data)=>new(data.ToArray());
    private static byte[] Create(GameVersion version,int revision,int gender)
    {
        var s=Open(SwshBlockFixtureTests.Create(version,revision));var blocks=s.AllBlocks.Select(b=>b.Key is SaveBlockAccessor8SWSH.KRotoRally or SaveBlockAccessor8SWSH.KBattleTowerSinglesVictory or SaveBlockAccessor8SWSH.KBattleTowerDoublesVictory||Counts.Contains(b.Key)?SwshBlockFixtureTests.Typed(b.Key,b.Data.ToArray(),SCTypeCode.UInt32):b.Key is SaveBlockAccessor8SWSH.KBattleTowerSinglesStreak or SaveBlockAccessor8SWSH.KBattleTowerDoublesStreak?SwshBlockFixtureTests.Typed(b.Key,b.Data.ToArray(),SCTypeCode.UInt16):b.Clone()).ToDictionary(b=>b.Key);
        // Blank templates omit some source-named Diglett flags. Only this typed engineering fixture adds them.
        // Production reads never create missing blocks or pad a synthetic file to a SaveUtil-recognized length.
        if(revision>0){foreach(uint key in Flags)blocks[key]=SwshBlockFixtureTests.Typed(key,[],SCTypeCode.Bool1);foreach(uint key in Counts)if(!blocks.ContainsKey(key))blocks[key]=SwshBlockFixtureTests.Typed(key,new byte[4],SCTypeCode.UInt32);}s=new(SwishCrypto.Encrypt(blocks.Values.OrderBy(b=>b.Key).ToArray()));
        s.MyStatus.Gender=s.MyStatus.GenderAppearance=(byte)gender;s.MyStatus.Data[0xAF]=0xA7;s.MyStatus.Data[0x89]=0xA7;BinaryPrimitives.WriteUInt64LittleEndian(s.MyStatus.Data[8..],gender==0?0xDA95FC34AFA29E9Ful:0xD9A6510BD62C8864ul);s.OT="TEST";s.TrainerCard.OT="CARD";s.TrainerCard.Number="123";s.MyStatus.Number="456";s.TrainerCard.StartedYear=2024;s.TrainerCard.StartedMonth=2;s.TrainerCard.StartedDay=29;s.Played.LastSavedDate=new DateTime(2024,2,29,12,34,0);s.MyStatus.Watt=12;s.SetRecord(22,10);s.SetRecord(47,2);s.SetRecord(48,3);s.SetValue(SaveBlockAccessor8SWSH.KBattleTowerSinglesVictory,4u);s.SetValue(SaveBlockAccessor8SWSH.KBattleTowerDoublesVictory,5u);s.PlayedMinutes=99;s.PlayedSeconds=99;s.Misc.BP=65535;s.Coordinates.M=10;s.Coordinates.X=1.25f;s.Coordinates.Z=2.5f;s.Coordinates.Y=3.75f;s.Coordinates.SX=1;s.Coordinates.SZ=1;s.Coordinates.SY=1;s.Coordinates.RX=.5f;s.Coordinates.RZ=0;s.Coordinates.RY=.25f;s.Coordinates.RW=1;s.Fashion.Data.Fill(0xA7);return s.Write().ToArray();
    }
    private static byte[] Compare(byte[] input,Tr8Edit edit,Action<SAV8SWSH> expected)
    {
        var original=input.ToArray();string hash=Br4Editing.Hash(input);var output=Trainer8Editing.Prepare(Open(input),edit with{SourceHash=hash},hash,input.Length,out _);var s=Open(input);expected(s);Check(output.SequenceEqual(s.Write().ToArray()),"Trainer8 independent full-file parity");Check(input.SequenceEqual(original),"Trainer8 immutable original");Trainer8Editing.Prepare(Open(input),edit with{SourceHash=hash,TargetHash=Br4Editing.Hash(output)},hash,input.Length,out _);return output;
    }
    private static void U32(SAV8SWSH s,uint key,uint value)=>BinaryPrimitives.WriteUInt32LittleEndian(s.Blocks.GetBlock(key).Data,value);
    private static void Record(SAV8SWSH s,int i,int n)=>BinaryPrimitives.WriteInt32LittleEndian(s.Blocks.GetBlock(0x37DA95A3).Data[(i*4)..],n);
    public static void Run()
    {
        foreach(var version in new[]{GameVersion.SW,GameVersion.SH})for(int revision=0;revision<=2;revision++)for(int gender=0;gender<2;gender++)
        {
            byte[] data=Create(version,revision,gender);var c=Trainer8Editing.Read(Open(data),Br4Editing.Hash(data));Check(c.Fields.Length==71&&c.CanEdit&&c.Position.CanEdit&&c.CardTeam.Length==6&&c.TitleTeam.Length==6,"Trainer8 complete catalog");
            Compare(data,new("patch",null,[new("number","中文5abcdef"),new("watt","9999999"),new("singleWins","9999999"),new("doubleWins","1234567"),new("singleStreak","999"),new("doubleStreak","999"),new("rally","99999"),new("bp","9999"),new("minutes","99"),new("seconds","99")]),s=>{byte[] number=[0x2D,0x87,0x35];number.CopyTo(s.MyStatus.Data[1..]);number.CopyTo(s.TrainerCard.Data[0x39..]);BinaryPrimitives.WriteUInt32LittleEndian(s.MyStatus.Data[0xD0..],9999999);Record(s,22,9999999);U32(s,0x436CAF2B,9999999);Record(s,47,9999999);U32(s,0x0D477836,1234567);Record(s,48,1234567);BinaryPrimitives.WriteUInt16LittleEndian(s.Blocks.GetBlock(0x6226F5AD).Data,300);BinaryPrimitives.WriteUInt16LittleEndian(s.Blocks.GetBlock(0x5F74FCEE).Data,300);BinaryPrimitives.WriteInt32LittleEndian(s.TrainerCard.Data[0x28..],99999);U32(s,0x38548020,99999);BinaryPrimitives.WriteUInt16LittleEndian(s.Misc.Data[0x11C..],9999);s.Played.Data[2]=s.Played.Data[3]=39;});
            Compare(data,new("ids",null,[new("tid","123456"),new("sid","1234")]),s=>BinaryPrimitives.WriteUInt32LittleEndian(s.MyStatus.Data[0xA0..],1234123456));
            Compare(data,new("patch",null,[new("language","2"),new("started","2060-12-31"),new("saved","4095-12-31T23:59:00"),new("record0","999999999")]),s=>{s.MyStatus.Data[0xA7]=2;U32(s,SaveBlockAccessor8SWSH.KGameLanguage,2);BinaryPrimitives.WriteUInt16LittleEndian(s.TrainerCard.Data[0x170..],2060);s.TrainerCard.Data[0x172]=12;s.TrainerCard.Data[0x173]=31;BinaryPrimitives.WriteUInt32LittleEndian(s.Played.Data[4..],2195u|(11u<<12)|(31u<<16)|(23u<<21)|(59u<<26));Record(s,0,999999999);});
            Compare(data,new("position",null,[new("map","18446744073709551615"),new("rotation","180"),new("sx","2.5")],UiLanguage:"en"),s=>{var p=s.Coordinates.Data;BinaryPrimitives.WriteUInt64LittleEndian(p[0x6000..],ulong.MaxValue);BinaryPrimitives.WriteSingleLittleEndian(p[0x20..],2.5f);BinaryPrimitives.WriteSingleLittleEndian(p[0x30..],0);BinaryPrimitives.WriteSingleLittleEndian(p[0x34..],1);BinaryPrimitives.WriteSingleLittleEndian(p[0x38..],0);BinaryPrimitives.WriteSingleLittleEndian(p[0x3C..],(float)Math.Cos(Math.PI/2));});
            Compare(data,new("trash",null,NameTarget:"cardName",Trash:new("text",Text:"友")),s=>{byte[] raw=new byte[26];int len=StringConverter8.SetString(raw,"友",12,StringConverterOption.ClearZero);raw.AsSpan(0,len).CopyTo(s.TrainerCard.Data[0..26]);});
            Compare(data,new("resave",null),s=>{BinaryPrimitives.WriteUInt64LittleEndian(s.MyStatus.Data[0x88..],gender==0?0xE2245380DA099773ul:0x00ECCDE1E75B6B3Ful);s.TrainerCard.Data.Slice(0x39,3).CopyTo(s.MyStatus.Data[1..]);BinaryPrimitives.WriteUInt16LittleEndian(s.Misc.Data[0x11C..],9999);s.Played.Data[2]=s.Played.Data[3]=39;Record(s,22,12);Record(s,47,4);Record(s,48,5);var p=s.Coordinates.Data;BinaryPrimitives.WriteSingleLittleEndian(p[0x30..],0);BinaryPrimitives.WriteSingleLittleEndian(p[0x38..],0);});
            var before=Open(data);var appearance=Trainer8Editing.Prepare(before,new("patch",c.SourceHash,[new("gender",(1-gender).ToString())]),c.SourceHash,data.Length,out _);var changed=Open(appearance);Check(changed.Gender==1-gender&&changed.MyStatus.GenderAppearance==1-gender&&(int)PlayerSkinColor8Extensions.GetSkinColorFromSkin(changed.MyStatus.Skin)==1-gender&&changed.MyStatus.Data[0xAF]==0xA7,"Trainer8 gender resets matching appearance and preserves reserved bytes");
            foreach(string mode in new[]{"base","legal","all"}){var output=Trainer8Editing.Prepare(Open(data),new("fashion",c.SourceHash,Fashion:mode),c.SourceHash,data.Length,out _);var updated=Open(output);Check(updated.Fashion.Data[..0x300].SequenceEqual(before.Fashion.Data[..0x300])&&updated.Fashion.Data.Slice(0x780,0x300).SequenceEqual(before.Fashion.Data.Slice(0x780,0x300)),"Trainer8 fashion leaves non-apparel regions");Check(updated.Fashion.Data.Slice(0x300,0x480).Contains((byte)0)&&!updated.Fashion.Data.SequenceEqual(before.Fashion.Data),"Trainer8 clears old apparel data before unlock");if(mode=="base")Check(updated.Fashion.Data.Slice(0xA80,0x480).IndexOfAnyExcept((byte)0)<0,"Trainer8 base fashion has cleared new region");}
            if(revision==0)Reject(()=>Trainer8Editing.Prepare(Open(data),new("diglett",c.SourceHash),c.SourceHash,data.Length,out _));else Compare(data,new("diglett",null),s=>{foreach(var (zone,max) in Zones){s.Blocks.GetBlock(Hash($"z_wr{zone:0000}_F_DHIGUDA")).ChangeBooleanType(SCTypeCode.Bool2);for(int i=0;i<=max;i++)s.Blocks.GetBlock(Hash($"z_wr{zone:0000}_F_DHIGUDA_{i}")).ChangeBooleanType(SCTypeCode.Bool2);U32(s,Hash($"WK_EV_R1_DHIG_WR{zone:0000}"),(uint)(max+2+(zone==223?2:0)));}foreach(string n in new[]{"z_wr0223_F_TRIO","FE_R1_DHIGUDA_TRIO"})s.Blocks.GetBlock(Hash(n)).ChangeBooleanType(SCTypeCode.Bool2);U32(s,Hash("WK_EV_R1_DHIGUDA_ADD"),150);U32(s,Hash("WK_EV_R1_DHIGUDA_COUNT"),1);U32(s,Hash("WK_EV_R1_DHIGUDA_PROGRESS"),1);});
            foreach(var edit in new[]{new Tr8Edit("patch",c.SourceHash,[new("bp","10000")]),new("patch",c.SourceHash,[new("hours","65536")]),new("patch",c.SourceHash,[new("started","2061-01-01")]),new("fashion",c.SourceHash,Fashion:"invalid"),new("trash",c.SourceHash,NameTarget:"invalid",Trash:new("clear")),new("invalid",c.SourceHash),new("resave",new string('0',64)),new("patch",c.SourceHash,[new("money","1")],TargetHash:new string('0',64))})Reject(()=>Trainer8Editing.Prepare(Open(data),edit,c.SourceHash,data.Length,out _));var invalid=Open(data);invalid.Coordinates.X=float.NaN;Check(!Trainer8Editing.Read(invalid,c.SourceHash).Position.CanEdit,"Trainer8 invalid coordinate disabled");Reject(()=>Trainer8Editing.Prepare(invalid,new("position",c.SourceHash,[new("x","0")]),c.SourceHash,data.Length,out _));
            foreach(string team in new[]{"card","title"})Compare(data,new("team",null,UiLanguage:"zh",Team:team,Members:[new(5,"ec","0xFFFFFFFF"),new(5,"formArgument","-2147483648")]),s=>{var raw=s.Blocks.GetBlock(team=="card"?0x874DA6FAu:0xE9BE28BFu).Data;int offset=team=="card"?0xC8+5*0x1C:5*0x28;BinaryPrimitives.WriteUInt32LittleEndian(raw[(offset+0x10)..],uint.MaxValue);BinaryPrimitives.WriteInt32LittleEndian(raw[(offset+(team=="card"?0x18:0x14))..],int.MinValue);});
            var flagFixture=Open(data);var flagBlocks=flagFixture.AllBlocks.Select(b=>b.Clone()).Append(SwshBlockFixtureTests.Typed(0xFFFFFFFE,[],SCTypeCode.Bool1)).OrderBy(b=>b.Key).ToArray();var flagData=SwishCrypto.Encrypt(flagBlocks);var beforeBlocks=new SAV8SWSH(flagData.ToArray());var afterBlocks=new SAV8SWSH(flagData.ToArray());var boolean=afterBlocks.Blocks.GetBlock(0xFFFFFFFE);var oldBooleanType=boolean.Type;boolean.ChangeBooleanType(oldBooleanType==SCTypeCode.Bool1?SCTypeCode.Bool2:SCTypeCode.Bool1);var blockChanges=Trainer8Editing.Changes(beforeBlocks,afterBlocks);Check(blockChanges.Length==1&&blockChanges[0].Before==""&&blockChanges[0].After==""&&blockChanges[0].BeforeType==oldBooleanType.ToString()&&blockChanges[0].AfterType==boolean.Type.ToString(),"Trainer8 previews boolean-only metadata changes");
            Check(c.CanDiglett==(revision>0),"Trainer8 checks all Diglett blocks and types");
            if(revision>0){var incomplete=Open(data);var missing=incomplete.AllBlocks.Where(b=>b.Key!=0x90189DE0).Select(b=>b.Clone()).ToArray();var absent=new SAV8SWSH(SwishCrypto.Encrypt(missing));Check(!Trainer8Editing.Read(absent,c.SourceHash).CanDiglett,"Trainer8 incomplete Diglett disabled");Reject(()=>Trainer8Editing.Prepare(absent,new("diglett",c.SourceHash),c.SourceHash,absent.Write().Length,out _));}
            if(version==GameVersion.SW&&revision==0&&gender==0)
            {
                Reject(()=>Trainer8Editing.Prepare(Open(data),new("patch",c.SourceHash,[new("hours","")]),c.SourceHash,data.Length,out _));
                Compare(data,new("patch",null,[new("bp",""),new("minutes",""),new("seconds","")]),s=>{BinaryPrimitives.WriteUInt16LittleEndian(s.Misc.Data[0x11C..],9999);s.Played.Data[2]=s.Played.Data[3]=0;});
                var zero=Open(data);var position=zero.Coordinates.Data;foreach(int offset in new[]{0x10,0x14,0x18,0x20,0x24,0x28,0x34})BinaryPrimitives.WriteSingleLittleEndian(position[offset..],0);BinaryPrimitives.WriteUInt64LittleEndian(position[0x6000..],0);BinaryPrimitives.WriteSingleLittleEndian(position[0x3C..],1);var zeroData=zero.Write().ToArray();
                Compare(zeroData,new("position",null,[new("map","0")],UiLanguage:"en"),_=>{});
                Compare(zeroData,new("position",null,[new("map","1")],UiLanguage:"en"),s=>{var p=s.Coordinates.Data;BinaryPrimitives.WriteUInt64LittleEndian(p[0x6000..],1);BinaryPrimitives.WriteSingleLittleEndian(p[0x30..],0);BinaryPrimitives.WriteSingleLittleEndian(p[0x38..],0);});
                foreach(var (old,expected) in new[]{(new DateTime(2061,2,3,4,5,0),new DateTime(2061,2,3)),(new DateTime(4095,12,31,23,59,0),new DateTime(2000,1,1)),(new DateTime(1900,1,1,12,34,0),new DateTime(1900,1,1))})
                {
                    var source=Open(data);source.Played.LastSavedDate=old;var encoded=source.Write().ToArray();var hash=Br4Editing.Hash(encoded);Check(!Trainer8Editing.Read(Open(encoded),hash).Fields.Any(f=>f.Key=="saved"),"Hidden date not directly editable");var output=Trainer8Editing.Prepare(Open(encoded),new("resave",hash),hash,encoded.Length,out _);Check(Open(output).Played.LastSavedDate==expected,"Source hidden date/time controls retain deterministic Designer values");
                }
            }
            Console.WriteLine($"PASS Trainer8 {version}/revision {revision}/gender {gender}: 71 fields, independent raw full-file parity, IDs/names/date/map/records, appearance/fashion/Diglett, hidden Designer dates and atomic rejection; synthetic typed blocks only, no SaveService/real-save acceptance");
        }
    }
